package ai.nexusone.service; import ai.nexusone.dto.*; import ai.nexusone.entity.*; import ai.nexusone.enums.*; import ai.nexusone.exception.*; import ai.nexusone.repository.*; import ai.nexusone.specification.*; import org.springframework.data.domain.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.*; import java.util.*; import java.util.function.ToDoubleFunction;
@Service @Transactional public class AutonomousEnterpriseStrategicGrowthService { private final AutonomousEnterpriseStrategicGrowthRepository r; public AutonomousEnterpriseStrategicGrowthService(AutonomousEnterpriseStrategicGrowthRepository r){this.r=r;}
 public AutonomousEnterpriseStrategicGrowthResponse generate(AutonomousEnterpriseStrategicGrowthRequest q){var e=new AutonomousEnterpriseStrategicGrowth();e.setTitle(q.title());e.setGrowthVision(q.growthVision());e.setGrowthStrategy(q.growthStrategy());e.setMarketExpansionPlan(q.marketExpansionPlan());e.setCustomerGrowthStrategy(q.customerGrowthStrategy());e.setProductPortfolioGrowth(q.productPortfolioGrowth());e.setDigitalGrowthTransformation(q.digitalGrowthTransformation());e.setPartnerEcosystemGrowth(q.partnerEcosystemGrowth());e.setGrowthRiskAssessment(q.growthRiskAssessment());e.setVisionScore(q.visionScore());e.setGrowthStrategyScore(q.growthStrategyScore());e.setMarketExpansionScore(q.marketExpansionScore());e.setCustomerGrowthScore(q.customerGrowthScore());e.setProductGrowthScore(q.productGrowthScore());e.setDigitalGrowthScore(q.digitalGrowthScore());e.setEcosystemGrowthScore(q.ecosystemGrowthScore());e.setExecutionScore(q.executionScore());e.setStrategicGrowthScore(Math.round((q.visionScore()+q.growthStrategyScore()+q.marketExpansionScore()+q.customerGrowthScore()+q.productGrowthScore()+q.digitalGrowthScore()+q.ecosystemGrowthScore()+q.executionScore())/8.0*100.0)/100.0);e.setPriority(q.priority());e.setCreatedBy(q.createdBy());e.setStatus(AutonomousEnterpriseStrategicGrowthStatus.GENERATED);return map(r.save(e));}
 @Transactional(readOnly=true) public AutonomousEnterpriseStrategicGrowthResponse get(Long id){return map(find(id));} @Transactional(readOnly=true) public Page<AutonomousEnterpriseStrategicGrowthResponse> history(Pageable p){return r.findAll(p).map(this::map);} @Transactional(readOnly=true) public Page<AutonomousEnterpriseStrategicGrowthResponse> search(String k,AutonomousEnterpriseStrategicGrowthPriority p,AutonomousEnterpriseStrategicGrowthStatus s,Pageable pg){return r.findAll(AutonomousEnterpriseStrategicGrowthSpecification.filter(k,p,s),pg).map(this::map);}
 public AutonomousEnterpriseStrategicGrowthResponse review(Long id,AutonomousEnterpriseStrategicGrowthActionRequest q){var e=find(id);need(e,AutonomousEnterpriseStrategicGrowthStatus.GENERATED,"Only GENERATED reports can be reviewed");e.setStatus(AutonomousEnterpriseStrategicGrowthStatus.REVIEWED);e.setReviewedBy(q.actionBy());e.setReviewedAt(LocalDateTime.now());return map(r.save(e));}
 public AutonomousEnterpriseStrategicGrowthResponse approve(Long id,AutonomousEnterpriseStrategicGrowthActionRequest q){var e=find(id);need(e,AutonomousEnterpriseStrategicGrowthStatus.REVIEWED,"Only REVIEWED reports can be approved");e.setStatus(AutonomousEnterpriseStrategicGrowthStatus.APPROVED);e.setDecidedBy(q.actionBy());e.setDecidedAt(LocalDateTime.now());return map(r.save(e));}
 public AutonomousEnterpriseStrategicGrowthResponse reject(Long id,AutonomousEnterpriseStrategicGrowthActionRequest q){var e=find(id);if(e.getStatus()!=AutonomousEnterpriseStrategicGrowthStatus.GENERATED&&e.getStatus()!=AutonomousEnterpriseStrategicGrowthStatus.REVIEWED)throw new IllegalStateException("Only GENERATED or REVIEWED reports can be rejected");e.setStatus(AutonomousEnterpriseStrategicGrowthStatus.REJECTED);e.setDecidedBy(q.actionBy());e.setDecidedAt(LocalDateTime.now());return map(r.save(e));}
 public AutonomousEnterpriseStrategicGrowthResponse publish(Long id,AutonomousEnterpriseStrategicGrowthActionRequest q){var e=find(id);need(e,AutonomousEnterpriseStrategicGrowthStatus.APPROVED,"Only APPROVED reports can be published");e.setStatus(AutonomousEnterpriseStrategicGrowthStatus.PUBLISHED);e.setPublishedBy(q.actionBy());e.setPublishedAt(LocalDateTime.now());return map(r.save(e));}
 @Transactional(readOnly=true) public AutonomousEnterpriseStrategicGrowthAnalyticsResponse analytics(){var a=r.findAll();return new AutonomousEnterpriseStrategicGrowthAnalyticsResponse(a.size(),cnt(a,AutonomousEnterpriseStrategicGrowthStatus.GENERATED),cnt(a,AutonomousEnterpriseStrategicGrowthStatus.REVIEWED),cnt(a,AutonomousEnterpriseStrategicGrowthStatus.APPROVED),cnt(a,AutonomousEnterpriseStrategicGrowthStatus.REJECTED),cnt(a,AutonomousEnterpriseStrategicGrowthStatus.PUBLISHED),avg(a,AutonomousEnterpriseStrategicGrowth::getVisionScore),avg(a,AutonomousEnterpriseStrategicGrowth::getGrowthStrategyScore),avg(a,AutonomousEnterpriseStrategicGrowth::getMarketExpansionScore),avg(a,AutonomousEnterpriseStrategicGrowth::getCustomerGrowthScore),avg(a,AutonomousEnterpriseStrategicGrowth::getProductGrowthScore),avg(a,AutonomousEnterpriseStrategicGrowth::getDigitalGrowthScore),avg(a,AutonomousEnterpriseStrategicGrowth::getEcosystemGrowthScore),avg(a,AutonomousEnterpriseStrategicGrowth::getExecutionScore),avg(a,AutonomousEnterpriseStrategicGrowth::getStrategicGrowthScore));}
 private long cnt(List<AutonomousEnterpriseStrategicGrowth> a,AutonomousEnterpriseStrategicGrowthStatus s){return a.stream().filter(x->x.getStatus()==s).count();} private double avg(List<AutonomousEnterpriseStrategicGrowth> a,ToDoubleFunction<AutonomousEnterpriseStrategicGrowth> f){return Math.round(a.stream().mapToDouble(f).average().orElse(0)*100.0)/100.0;} private AutonomousEnterpriseStrategicGrowth find(Long id){return r.findById(id).orElseThrow(()->new AutonomousEnterpriseStrategicGrowthNotFoundException(id));} private void need(AutonomousEnterpriseStrategicGrowth e,AutonomousEnterpriseStrategicGrowthStatus s,String m){if(e.getStatus()!=s)throw new IllegalStateException(m);} private AutonomousEnterpriseStrategicGrowthResponse map(AutonomousEnterpriseStrategicGrowth e){return new AutonomousEnterpriseStrategicGrowthResponse(e.getId(),e.getTitle(),e.getGrowthVision(),e.getGrowthStrategy(),e.getMarketExpansionPlan(),e.getCustomerGrowthStrategy(),e.getProductPortfolioGrowth(),e.getDigitalGrowthTransformation(),e.getPartnerEcosystemGrowth(),e.getGrowthRiskAssessment(),e.getVisionScore(),e.getGrowthStrategyScore(),e.getMarketExpansionScore(),e.getCustomerGrowthScore(),e.getProductGrowthScore(),e.getDigitalGrowthScore(),e.getEcosystemGrowthScore(),e.getExecutionScore(),e.getStrategicGrowthScore(),e.getPriority(),e.getStatus(),e.getCreatedBy(),e.getReviewedBy(),e.getReviewedAt(),e.getDecidedBy(),e.getDecidedAt(),e.getPublishedBy(),e.getPublishedAt(),e.getCreatedAt(),e.getUpdatedAt());}
}
